namespace sv_e154e83089064088873f3d305422dd75;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

public class PersonalInfoModel
{
    public string FullName { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";
    public string Address { get; set; } = "";
}

public class WorkEntryModel
{
    public string Company { get; set; } = "";
    public string Title { get; set; } = "";
    public DateTime? StartDate { get; set; }
    public DateTime? EndDate { get; set; }
    public bool IsCurrent { get; set; }
    public string Description { get; set; } = "";
}

public class ReferenceModel
{
    public string Name { get; set; } = "";
    public string Relationship { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";
}

.step-indicator {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0 0 2rem;
    counter-reset: step;
}

.step-item {
    flex: 1;
    text-align: center;
    position: relative;
}

.step-item:not(:last-child)::after {
    content: "";
    position: absolute;
    top: 18px;
    left: calc(50% + 20px);
    width: calc(100% - 40px);
    height: 2px;
    background: #dee2e6;
}

.step-item.completed:not(:last-child)::after {
    background: #198754;
}

.step-button {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.5rem;
    background: none;
    border: none;
    cursor: default;
    padding: 0;
    width: 100%;
    color: inherit;
    font: inherit;
}

.completed .step-button {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.875rem;
    border: 2px solid #dee2e6;
    background: #fff;
    color: #adb5bd;
    position: relative;
    z-index: 1;
}

.active .step-circle {
    border-color: #0d6efd;
    background: #0d6efd;
    color: #fff;
}

.completed .step-circle {
    border-color: #198754;
    background: #198754;
    color: #fff;
}

.step-label {
    font-size: 0.8rem;
    color: #adb5bd;
}

.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.completed .step-label {
    color: #198754;
}

@if (ApplicationId is not null)
{
    <div class="card border-success">
        <div class="card-body text-center py-5">
            <div class="text-success mb-3" style="font-size: 3rem;">&#10003;</div>
            <h3 class="text-success">Application Submitted!</h3>
            <p class="lead">Your application ID is <strong>#@ApplicationId</strong></p>
            <p class="text-muted">We will review your application and get back to you soon.</p>
        </div>
    </div>
}
else
{
    <div class="card">
        <div class="card-body">
            <h4 class="card-title mb-4">Review &amp; Submit</h4>

            @if (!string.IsNullOrEmpty(errorMessage))
            {
                <div class="alert alert-danger">@errorMessage</div>
            }

            <!-- Personal Info -->
            <div class="mb-4">
                <div class="d-flex justify-content-between align-items-center mb-2">
                    <h5 class="mb-0">Personal Information</h5>
                    <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
                </div>
                <dl class="row mb-0">
                    <dt class="col-sm-3">Name</dt>
                    <dd class="col-sm-9">@Personal.FullName</dd>
                    <dt class="col-sm-3">Email</dt>
                    <dd class="col-sm-9">@Personal.Email</dd>
                    <dt class="col-sm-3">Phone</dt>
                    <dd class="col-sm-9">@Personal.Phone</dd>
                    <dt class="col-sm-3">Address</dt>
                    <dd class="col-sm-9">@Personal.Address</dd>
                </dl>
            </div>
            <hr />

            <!-- Work History -->
            <div class="mb-4">
                <div class="d-flex justify-content-between align-items-center mb-2">
                    <h5 class="mb-0">Work History</h5>
                    <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
                </div>
                @foreach (var entry in WorkEntries.Where(e => !string.IsNullOrWhiteSpace(e.Company)))
                {
                    <div class="mb-2 ps-3 border-start">
                        <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                        <small class="text-muted">
                            @(entry.StartDate?.ToString("MMM yyyy") ?? "N/A") &ndash;
                            @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                        </small>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="mb-0 mt-1">@entry.Description</p>
                        }
                    </div>
                }
            </div>
            <hr />

            <!-- References -->
            <div class="mb-4">
                <div class="d-flex justify-content-between align-items-center mb-2">
                    <h5 class="mb-0">References</h5>
                    <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
                </div>
                @foreach (var reference in References.Where(r => !string.IsNullOrWhiteSpace(r.Name)))
                {
                    <div class="mb-2 ps-3 border-start">
                        <strong>@reference.Name</strong> &mdash; @reference.Relationship<br />
                        <small class="text-muted">@reference.Email &bull; @reference.Phone</small>
                    </div>
                }
            </div>
            <hr />

            <!-- Cover Letter -->
            <div class="mb-4">
                <div class="d-flex justify-content-between align-items-center mb-2">
                    <h5 class="mb-0">Cover Letter</h5>
                    <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(4)">Edit</button>
                </div>
                <p class="mb-0" style="white-space: pre-wrap;">@(string.IsNullOrWhiteSpace(CoverLetter) ? "(No cover letter provided)" : CoverLetter)</p>
            </div>

            <div class="d-flex justify-content-end mt-4">
                <button class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@IsSubmitting">
                    @if (IsSubmitting)
                    {
                        <span class="spinner-border spinner-border-sm me-2" role="status"></span>
                        <span>Submitting...</span>
                    }
                    else
                    {
                        <span>Submit Application</span>
                    }
                </button>
            </div>
        </div>
    </div>
}

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public int? ApplicationId { get; set; }

    private string? errorMessage;

    private async Task HandleSubmit()
    {
        errorMessage = null;
        try
        {
            await OnSubmit.InvokeAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Submission failed: {ex.Message}. Please try again.";
        }
    }
}

