{"path": "/tmp/sv-e154e83089064088873f3d305422dd75/Components/JobApplication/StepIndicator.razor", "file_text": "<nav aria-label="Application progress">
    <ol class="step-indicator">
        @for (int i = 0; i < steps.Length; i++)
        {
            var stepNumber = i + 1;
            var isActive = stepNumber == CurrentStep;
            var isCompleted = CompletedSteps.Contains(stepNumber);
            var cssClass = isActive ? "active" : isCompleted ? "completed" : "pending";

            <li class="step-item @cssClass">
                @if (isCompleted)
                {
                    <button class="step-button" @onclick="() => OnStepClicked.InvokeAsync(stepNumber)">
                        <span class="step-circle">&#10003;</span>
                        <span class="step-label">@steps[i]</span>
                    </button>
                }
                else
                {
                    <span class="step-button" aria-current="@(isActive ? "step" : null)">
                        <span class="step-circle">@stepNumber</span>
                        <span class="step-label">@steps[i]</span>
                    </span>
                }
            </li>
        }
    </ol>
</nav>

@code {
