{"path": "/tmp/sv-e154e83089064088873f3d305422dd75/Components/JobApplication/PersonalInfoStep.razor", "file_text": "<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Personal Information</h4>

        @if (!string.IsNullOrEmpty(validationMessage))
        {
            <div class="alert alert-danger">@validationMessage</div>
        }

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Full Name <span class="text-danger">*</span></label>
                <input class="form-control" @bind="Model.FullName" @bind:event="oninput" placeholder="John Doe" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Email <span class="text-danger">*</span></label>
                <input type="email" class="form-control @(EmailError is not null ? "is-invalid" : "")"
                       @bind="Model.Email" @bind:event="oninput" placeholder="john@example.com" />
                @if (EmailError is not null)
                {
                    <div class="invalid-feedback">@EmailError</div>
                }
            </div>
            <div class="col-md-6">
                <label class="form-label">Phone <span class="text-danger">*</span></label>
                <input type="tel" class="form-control" @bind="Model.Phone" @bind:event="oninput" placeholder="(555) 123-4567" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Address <span class="text-danger">*</span></label>
                <input class="form-control" @bind="Model.Address" @bind:event="oninput" placeholder="123 Main St, City, State" />
            </div>
        </div>

        <div class="d-flex justify-content-end mt-4">
            <button class="btn btn-primary" @onclick="HandleNext">Next &rarr;</button>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public string? EmailError { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }

    private string? validationMessage;

    private async Task HandleNext()
    {
        validationMessage = null;

        if (string.IsNullOrWhiteSpace(Model.FullName) ||
            string.IsNullOrWhiteSpace(Model.Email) ||
            string.IsNullOrWhiteSpace(Model.Phone) ||
            string.IsNullOrWhiteSpace(Model.Address))
        {
            validationMessage = "Please fill in all required fields.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}
"}

{"path": "/tmp/sv-e154e83089064088873f3d305422dd75/Components/JobApplication/WorkHistoryStep.razor", "file_text": "<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Work History</h4>

        @if (!string.IsNullOrEmpty(validationMessage))
        {
            <div class="alert alert-danger">@validationMessage</div>
        }

        @for (int i = 0; i < Entries.Count; i++)
        {
            var index = i;
            <WorkEntryForm Model="Entries[index]" Index="index + 1"
                           CanRemove="Entries.Count > 1"
                           OnRemove="() => RemoveEntry(index)" />
        }

        <button type="button" class="btn btn-outline-secondary mb-4" @onclick="AddEntry">
            + Add Another Position
        </button>

        <div class="d-flex justify-content-between">
            <button class="btn btn-outline-secondary" @onclick="OnBack">&larr; Back</button>
            <button class="btn btn-primary" @onclick="HandleNext">Next &rarr;</button>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? validationMessage;

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        validationMessage = null;

        if (!Entries.Any(e => !string.IsNullOrWhiteSpace(e.Company) && !string.IsNullOrWhiteSpace(e.Title)))
        {
            validationMessage = "Please add at least one work entry with a company name and job title.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}
"}

{"path": "/tmp/sv-e154e83089064088873f3d305422dd75/Components/JobApplication/ReferencesStep.razor", "file_text": "<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">References</h4>

        @if (!string.IsNullOrEmpty(validationMessage))
        {
            <div class="alert alert-danger">@validationMessage</div>
        }

        @for (int i = 0; i < References.Count; i++)
        {
            var index = i;
            <ReferenceForm Model="References[index]" Index="index + 1"
                           CanRemove="References.Count > 2"
                           OnRemove="() => RemoveReference(index)" />
        }

        @if (References.Count < 3)
        {
            <button type="button" class="btn btn-outline-secondary mb-4" @onclick="AddReference">
                + Add Reference
            </button>
        }

        <div class="d-flex justify-content-between">
            <button class="btn btn-outline-secondary" @onclick="OnBack">&larr; Back</button>
            <button class="btn btn-primary" @onclick="HandleNext">Next &rarr;</button>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? validationMessage;

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        validationMessage = null;

        if (!References.Any(r => !string.IsNullOrWhiteSpace(r.Name) && !string.IsNullOrWhiteSpace(r.Email)))
        {
            validationMessage = "Please provide at least one reference with a name and email.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}
"}

{"path": "/tmp/sv-e154e83089064088873f3d305422dd75/Components/JobApplication/CoverLetterStep.razor", "file_text": "<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Cover Letter</h4>

        <div class="mb-3">
            <textarea class="form-control" rows="12" @bind="CoverLetter" @bind:event="oninput"
                      @bind:after="NotifyChanged" placeholder="Write your cover letter here..."
                      maxlength="@MaxCharacters"></textarea>
            <div class="form-text text-end">
                @(CoverLetter?.Length ?? 0) / @MaxCharacters characters
            </div>
        </div>

        <div class="d-flex justify-content-between">
            <button class="btn btn-outline-secondary" @onclick="OnBack">&larr; Back</button>
            <button class="btn btn-primary" @onclick="OnNext">Next &rarr;</button>
        </div>
    </div>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public int MaxCharacters { get; set; } = 2000;

    private async Task NotifyChanged()
    {
        await CoverLetterChanged.InvokeAsync(CoverLetter);
    }
}
"}

{"path": "/tmp/sv-e154e83089064088873f3d305422dd75/Components/JobApplication/ReviewStep.razor", "file_text": "@if (ApplicationId is not null)
{
    <div class="card border-success">
        <div class="card-body text-center py-5">
            <div class="text-success mb-3" style="font-size: 3rem;">&#10003;</div>
            <h3 class="text-success">Application Submitted!</h3>
            <p class="lead">Your application ID is <strong>#@ApplicationId</strong></p>
            <p class="text-muted">We will review your application and get back to you soon.</p>
        </div>
    </div>
}
else
{
    <div class="card">
        <div class="card-body">
            <h4 class="card-title mb-4">Review &amp; Submit</h4>

            @if (!string.IsNullOrEmpty(errorMessage))
            {
                <div class="alert alert-danger">@errorMessage</div>
            }

            <!-- Personal Info -->
            <div class="mb-4">
                <div class="d-flex justify-content-between align-items-center mb-2">
                    <h5 class="mb-0">Personal Information</h5>
                    <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
                </div>
                <dl class="row mb-0">
                    <dt class="col-sm-3">Name</dt>
                    <dd class="col-sm-9">@Personal.FullName</dd>
                    <dt class="col-sm-3">Email</dt>
                    <dd class="col-sm-9">@Personal.Email</dd>
                    <dt class="col-sm-3">Phone</dt>
                    <dd class="col-sm-9">@Personal.Phone</dd>
                    <dt class="col-sm-3">Address</dt>
                    <dd class="col-sm-9">@Personal.Address</dd>
                </dl>
            </div>
            <hr />

            <!-- Work History -->
            <div class="mb-4">
                <div class="d-flex justify-content-between align-items-center mb-2">
                    <h5 class="mb-0">Work History</h5>
                    <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
                </div>
                @foreach (var entry in WorkEntries.Where(e => !string.IsNullOrWhiteSpace(e.Company)))
                {
                    <div class="mb-2 ps-3 border-start">
                        <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                        <small class="text-muted">
                            @(entry.StartDate?.ToString("MMM yyyy") ?? "N/A") &ndash;
                            @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                        </small>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="mb-0 mt-1">@entry.Description</p>
                        }
                    </div>
                }
            </div>
            <hr />

            <!-- References -->
            <div class="mb-4">
                <div class="d-flex justify-content-between align-items-center mb-2">
                    <h5 class="mb-0">References</h5>
                    <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
                </div>
                @foreach (var reference in References.Where(r => !string.IsNullOrWhiteSpace(r.Name)))
                {
                    <div class="mb-2 ps-3 border-start">
                        <strong>@reference.Name</strong> &mdash; @reference.Relationship<br />
                        <small class="text-muted">@reference.Email &bull; @reference.Phone</small>
                    </div>
                }
            </div>
            <hr />

            <!-- Cover Letter -->
            <div class="mb-4">
                <div class="d-flex justify-content-between align-items-center mb-2">
                    <h5 class="mb-0">Cover Letter</h5>
                    <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(4)">Edit</button>
                </div>
                <p class="mb-0" style="white-space: pre-wrap;">@(string.IsNullOrWhiteSpace(CoverLetter) ? "(No cover letter provided)" : CoverLetter)</p>
            </div>

            <div class="d-flex justify-content-end mt-4">
                <button class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@IsSubmitting">
                    @if (IsSubmitting)
                    {
                        <span class="spinner-border spinner-border-sm me-2" role="status"></span>
                        <span>Submitting...</span>
                    }
                    else
                    {
                        <span>Submit Application</span>
                    }
                </button>
            </div>
        </div>
    </div>
}

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public int? ApplicationId { get; set; }

    private string? errorMessage;

    private async Task HandleSubmit()
    {
        errorMessage = null;
        try
        {
            await OnSubmit.InvokeAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Submission failed: {ex.Message}. Please try again.";
        }
    }
}
"}

