.step-indicator {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0 0 2rem;
    counter-reset: step;
}

.step-item {
    flex: 1;
    text-align: center;
    position: relative;
}

.step-item:not(:last-child)::after {
    content: "";
    position: absolute;
    top: 18px;
    left: calc(50% + 20px);
    width: calc(100% - 40px);
    height: 2px;
    background: #dee2e6;
}

.step-item.completed:not(:last-child)::after {
    background: #198754;
}

.step-button {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.5rem;
    background: none;
    border: none;
    cursor: default;
    padding: 0;
    width: 100%;
    color: inherit;
    font: inherit;
}

.completed .step-button {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.875rem;
    border: 2px solid #dee2e6;
    background: #fff;
    color: #adb5bd;
    position: relative;
    z-index: 1;
}

.active .step-circle {
    border-color: #0d6efd;
    background: #0d6efd;
    color: #fff;
}

.completed .step-circle {
    border-color: #198754;
    background: #198754;
    color: #fff;
}

.step-label {
    font-size: 0.8rem;
    color: #adb5bd;
}

.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.completed .step-label {
    color: #198754;
}

